"""Accessible, self-contained local coding dashboard page."""

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>LocalCodingAgent | Coding workspace</title><style>
:root{font:16px/1.5 system-ui,Segoe UI,sans-serif;color:#172533;background:#eef2f6}*{box-sizing:border-box}body{margin:0}header{background:#123853;color:#fff;padding:1.1rem max(1rem,calc((100% - 1180px)/2))}header h1{margin:0;font-size:1.55rem}header p{margin:.2rem 0;color:#deebf4}nav{position:sticky;top:0;background:#fff;border-bottom:1px solid #cbd5df;padding:.55rem max(1rem,calc((100% - 1180px)/2));display:flex;gap:.5rem;flex-wrap:wrap;z-index:2}nav a{color:#123853;font-weight:650;padding:.4rem .65rem;border-radius:5px}nav a:focus,nav a:hover{background:#e7f0f6}main{max-width:1180px;margin:auto;padding:1rem}section,article{background:#fff;border:1px solid #d3dce5;border-radius:9px;padding:1rem;margin:1rem 0;box-shadow:0 1px 2px #183b5610}h2{margin:.1rem 0 .8rem;color:#123853;font-size:1.25rem}h3{margin:.1rem 0 .4rem}label{display:block;margin:.55rem 0;font-weight:600}input,select,textarea,button{font:inherit;padding:.55rem;border:1px solid #98a9b8;border-radius:5px}input,select,textarea{background:white;color:#172533;max-width:100%}textarea{width:100%;min-height:9rem}button{background:#14577e;color:#fff;cursor:pointer;font-weight:650}button.secondary{background:#fff;color:#243746}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #f0a329;outline-offset:2px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:.8rem}.metric{border-left:4px solid #287da5;padding:.5rem .8rem;background:#f5f8fa}.muted,.subtle{color:#526474;font-size:.93rem}.error{color:#8c271c;background:#fff1ef;padding:.65rem;border-radius:5px}.good{color:#176139}.warning{color:#704500;background:#fff7e6;padding:.7rem;border-left:5px solid #c47b08}.badge{display:inline-block;padding:.15rem .5rem;border-radius:10px;background:#e8eef3;font-weight:650}.finding{border-left:4px solid #b45e20;padding:.5rem;margin:.45rem 0;background:#fff9f3}pre{overflow:auto;max-height:28rem;max-width:100%;background:#101c27;color:#e9f0f6;padding:1rem;border-radius:5px;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}.path-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(210px,100%),1fr))}.path-list label{font-weight:400}details{margin:.6rem 0}summary{cursor:pointer;font-weight:650;color:#164b70}.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:.6rem;flex-wrap:wrap}.actions{display:flex;gap:.5rem;flex-wrap:wrap}.empty{padding:1rem;border:1px dashed #9eafbd;border-radius:6px;color:#526474}.two-col{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:1rem}main,section,article,.grid,.two-col,.card-head{min-width:0;max-width:100%}p,span,strong,label,summary,button,select,input,textarea,pre,.metric,.subtle,.warning,.error{overflow-wrap:anywhere;word-break:break-word}input,select{width:100%}.path-list input{width:auto}@media(max-width:750px){.two-col{grid-template-columns:1fr}main{padding:.6rem}header{padding:1rem}}
</style></head><body><header><h1>LocalCodingAgent</h1><p>Local coding workspace · planner, coder, and reviewer · Broker-controlled changes</p></header>
<nav aria-label="Dashboard sections"><a href="#new-task">Start a task</a><a href="#active">My workflows</a><a href="#history">Past tasks</a></nav><main>
<section id="login"><h2>Open your coding workspace</h2><p class="muted">In the PowerShell window that started the dashboard, copy the one-run token printed at startup. Paste it here. The token is not part of the web address.</p><label for="token">One-run dashboard token</label><input id="token" type="password" autocomplete="current-password"><button id="connect">Open dashboard</button><p id="message" role="status" aria-live="polite"></p><details><summary>Lost the token?</summary><p>Close only the dashboard window with Ctrl+C, then start it again from PowerShell. Keep that window open so you can copy the new token. Never paste the token into a URL or share it.</p></details></section>
<div id="app" hidden><details id="overview"><summary>System status (optional)</summary><p class="muted">“Connected” is the provider check from dashboard startup. Installed means the Mac reports the model; authorized means this dashboard is allowed to request it.</p><button id="refresh" class="secondary">Refresh status</button><div id="health" class="grid"></div><div id="counts" class="grid"></div><h3>Recent results</h3><div id="recent"></div></details>
<section id="new-task"><h2>Start a task</h2><p class="muted">Choose a disposable repository, describe the result you want, then submit. The agents will plan, draft, and review a proposal. Nothing is changed until you approve it through the separate Windows operator process.</p><label for="fixture">1. Choose a test project</label><select id="fixture"></select><label for="task">2. Describe what you want changed</label><textarea id="task" maxlength="12000" placeholder="Example: Add an average(values) function. Empty input should raise ValueError. Add tests for normal and empty input."></textarea><div class="actions"><button class="secondary example" data-example="Add a small function that validates its input, handles boundary values, and add tests for normal, boundary, and invalid inputs.">Insert example task</button><button class="secondary example" data-example="Fix the reported defect in the selected files. Preserve existing behavior and add a focused regression test for the failure case.">Insert bug-fix example</button></div><details><summary>Choose files and other options</summary><p class="muted">Only checked files can be proposed. Keep the selection limited to files needed for this task.</p><div id="paths" class="path-list"></div><div class="grid"><label for="timeout">Time limit for each role (seconds)<input id="timeout" type="number" min="30" max="600" step="1" value="120"></label><label for="attempts">How many proposal tries?<select id="attempts"><option value="1">1 try</option><option value="2">2 tries</option><option value="3" selected>3 tries</option></select></label></div></details>
<details><summary>Model settings (optional)</summary><label for="preset">Model setup</label><select id="preset"><option value="a">Recommended: all roles use qwen3-coder:30b</option><option value="b">Smaller planner: qwen3:8b; coder and reviewer use qwen3-coder:30b</option><option value="custom">Choose each role</option></select><div class="grid"><label for="planner">Planner model<select id="planner"></select></label><label for="coder">Coder model<select id="coder"></select></label><label for="reviewer">Reviewer model<select id="reviewer"></select></label></div><p id="model-status" class="muted"></p></details><button id="submit">Plan and draft proposal</button> <span id="submit-message" role="status" aria-live="polite"></span><p class="subtle">After submission, watch “My workflows.” Review the proposal there. Approval and applying changes happen outside this page.</p></section>
<section id="active"><h2>My workflows</h2><p class="muted">This is where you can follow planning, drafting, checks, and any proposal waiting for your review.</p><div id="workflows"></div></section><section id="history"><h2>Past tasks</h2><details><summary>Search or filter tasks (optional)</summary><div class="grid"><label for="search">Search by task or project<input id="search" type="search" placeholder="Type a task description or project name"></label><label for="state-filter">Filter by status<select id="state-filter"><option value="">All tasks</option><option value="awaiting_approval">Ready for your review</option><option value="completed">Finished</option><option value="failed">Stopped with an error</option><option value="cancelled">Cancelled</option><option value="interrupted">Interrupted</option><option value="rejected">Rejected</option><option value="timed_out">Time limit reached</option></select></label></div></details><div id="history-list"></div></section>
<details id="knowledge"><summary>Knowledge and saved lessons (optional)</summary><p class="muted">Read-only lessons from authorized disposable repositories. Lessons are not automatically promoted or used as instructions here.</p><div id="skill-counts" class="grid"></div><div id="skills"></div></details></div></main>
<script nonce="__NONCE__">
let token='',fixtures=[],models=[],allWorkflows=[];const $=id=>document.getElementById(id);
async function api(path,options={}){const r=await fetch(path,{...options,headers:{...(options.headers||{}),'Authorization':'Bearer '+token}});let j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.error||('Request failed ('+r.status+').'));return j}
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(cls)e.className=cls;return e}function item(parent,label,value){parent.append(node('p',label+': '+(value??'not recorded'),'subtle'))}
function drawPaths(){const box=$('paths');box.replaceChildren();const f=fixtures.find(x=>x.id===$('fixture').value);for(const path of f?.paths||[]){const l=node('label');const c=document.createElement('input');c.type='checkbox';c.value=path;c.checked=true;l.append(c,document.createTextNode(' '+path));box.append(l)}}
function applyPreset(){if($('preset').value==='a'){$('planner').value='qwen3-coder:30b';$('coder').value='qwen3-coder:30b';$('reviewer').value='qwen3-coder:30b'}else if($('preset').value==='b'){$('planner').value='qwen3:8b';$('coder').value='qwen3-coder:30b';$('reviewer').value='qwen3-coder:30b'}}
function drawModels(o){models=o.models||[];for(const id of ['planner','coder','reviewer']){const s=$(id),old=s.value;s.replaceChildren();for(const m of models){const x=node('option',m.name+' ('+(m.installed?'installed':o.provider?.status==='connected'?'not installed':'availability unchecked')+'; authorized)');x.value=m.name;s.append(x)}s.value=models.some(x=>x.name===old)?old:'qwen3-coder:30b'}$('model-status').textContent='Installed is based on the last provider model-list check. Authorized means included in the dashboard allowlist.'}
function drawOverview(o){const h=$('health'),p=o.provider||{};h.replaceChildren(node('div',(p.status==='connected'?'Connected':'Not connected')+' · '+(p.provider||'provider'),'metric'),node('div','Last provider check: '+(p.checked_at||'not checked')+' · '+(p.measurement||''),'metric'));for(const m of o.models||[])h.append(node('div',m.name+' · '+(m.installed?'installed':p.status==='connected'?'not installed':'availability unchecked')+' · authorized','metric'));const box=$('counts');box.replaceChildren();for(const [k,v] of Object.entries(o.workflow_counts||{}))box.append(node('div',k.replaceAll('_',' ')+': '+v,'metric'));for(const [k,v] of Object.entries(o.skill_counts||{}))box.append(node('div','skills '+k+': '+v,'metric'));const recent=$('recent');recent.replaceChildren();for(const w of o.recent_workflows||[]){const a=node('article');a.append(node('strong',w.task||w.run_id+' · '+w.state),node('p',w.state+' · '+w.tests+' · '+w.repository,'subtle'));if(w.failure)a.append(node('p',w.failure,'error'));recent.append(a)}if(!recent.childElementCount)recent.append(node('p','No completed or failed workflows yet.','empty'))}
function drawSkills(s){const c=$('skill-counts');c.replaceChildren();for(const [k,v] of Object.entries(s.counts||{}))c.append(node('div',k+': '+v,'metric'));const box=$('skills');box.replaceChildren();for(const x of s.skills||[]){const a=node('article');a.append(node('h3',(x.problem||x.skill_id)+' · '+x.status));item(a,'Candidate',x.skill_id+' v'+x.version+' · '+x.validation_state);item(a,'Project scope',x.project_id);item(a,'Category',x.category);if(x.source)item(a,'Provenance',JSON.stringify(x.source));box.append(a)}if(!box.childElementCount)box.append(node('p','No lessons are registered for these fixtures.','empty'))}
function friendlyState(s){return ({created:'Starting',planning:'Making a plan',generating:'Drafting a change',validating:'Checking the draft',reviewing:'Reviewing the draft',awaiting_approval:'Ready for your review',approved:'Approval recorded',applying:'Applying approved change',testing:'Running approved tests',completed:'Finished',failed:'Stopped with an error',cancelled:'Cancelled',interrupted:'Interrupted; needs checking',timed_out:'Time limit reached',rejected:'Proposal rejected'})[s]||'Status not recognized'}
function nextStep(s){return ({created:'The workflow is starting.',planning:'The planner is deciding what needs to change.',generating:'The coder is preparing a draft. Your files are not being changed.',validating:'Local checks are checking the draft and allowed files.',reviewing:'A separate reviewer is checking the validated draft.',awaiting_approval:'Read the proposed changes below. To apply them, use the separate Windows operator approval process.',approved:'The approval is recorded; the trusted local workflow is proceeding.',applying:'The approved change is being applied.',testing:'The approved test set is running.',completed:'The workflow finished. Check the test result below.',failed:'Read the error below. No automatic repair was made.',cancelled:'The workflow was cancelled.',interrupted:'The workflow stopped unexpectedly. Check its recovery details before doing anything else.',timed_out:'A model or workflow step exceeded its time limit.',rejected:'This proposal was rejected.'})[s]||'Open technical details for the recorded state.'}
function workflowCard(w){const c=node('article'),head=node('div',undefined,'card-head');head.append(node('h3',w.task||'Coding task'),node('span',friendlyState(w.state),'badge'));c.append(head,node('p',nextStep(w.state),'muted'));if(w.completion_verified)c.append(node('p','Verified: approved files match the expected contents and the trusted tests passed.','good'));else if(w.state==='completed')c.append(node('p','Marked finished, but the available evidence does not confirm every verification step.','warning'));if(w.failure)c.append(node('p','What stopped it: '+w.failure,'error'));const tech=node('details');tech.append(node('summary','Technical details (IDs, repository, models, timing)'));item(tech,'Workflow ID',w.run_id);item(tech,'Repository',w.repository);if(w.created_at)item(tech,'Created',new Date(w.created_at*1000).toLocaleString());if(w.updated_at)item(tech,'Last update',new Date(w.updated_at*1000).toLocaleString());if(w.active_role)item(tech,'Current step',w.active_role);item(tech,'Models',JSON.stringify(w.role_models||{}));if(w.elapsed_seconds!=null)item(tech,'Elapsed',Math.floor(w.elapsed_seconds)+' seconds');item(tech,'Model calls / retries',(w.model_invocation_count??0)+' / '+(w.status_summary?.retry_count??0));c.append(tech);
if(w.planner){const d=node('details');d.append(node('summary','Planner plan'),node('p',w.planner.summary));for(const x of w.planner.acceptance_criteria||[])d.append(node('p','Acceptance: '+x));for(const x of w.planner.test_requirements||[])d.append(node('p','Test requirement: '+x));c.append(d)}
if(w.validation_failures?.length){const d=node('details');d.append(node('summary','Correction attempts and validation failures ('+w.validation_failures.length+')'));for(const e of w.validation_failures)d.append(node('p','Attempt '+e.attempt+' · '+e.code+': '+e.message));c.append(d)}
if(w.patch_sha256){c.append(node('p','Changed files: '+(w.files||[]).join(', ')+' · '+(w.changed_lines?.added||0)+' added, '+(w.changed_lines?.removed||0)+' removed lines'));const d=node('details');d.append(node('summary','Review proposed diff'),node('pre',w.diff||'(diff unavailable)'));c.append(d);if(w.review){const r=node('details');r.append(node('summary','Independent reviewer (advisory)'),node('p',w.review.recommendation+': '+w.review.summary));for(const f of w.review.findings||[])r.append(node('div',f.severity+' · '+(f.path||'')+(f.line?':'+f.line:'')+' · '+f.message,'finding'));c.append(r)}const ev=node('details');ev.append(node('summary','Validation and test evidence'));item(ev,'Strict validation',JSON.stringify(w.validation));item(ev,'Simulated tests',JSON.stringify(w.simulation_tests));item(ev,'Broker tests',w.test_result?JSON.stringify({exit_code:w.test_result.exit_code,output:w.test_result.output}):'not run');item(ev,'Patch SHA-256',w.patch_sha256);item(ev,'Expected post-images',JSON.stringify(w.expected_post_images));c.append(ev)}
if(w.approval_required){const a=node('div',undefined,'warning');a.append(node('h3','Your review is needed before anything is changed'));item(a,'Project folder',w.repository);item(a,'Files in the proposal',(w.files||[]).join(', '));item(a,'Checks that will run',w.test_profile+' · '+w.test_command);a.append(node('p','Read the proposed changes and test results above. If you decide to proceed, use the separate Windows operator approval process. This web page cannot approve or apply changes.'));const exact=node('details');exact.append(node('summary','Exact approval identity (for the operator)'));item(exact,'Workflow ID',w.run_id);item(exact,'Baseline commit',w.baseline_commit);item(exact,'Patch SHA-256',w.patch_sha256);item(exact,'Authorized file allowlist',(w.allowed_paths||[]).join(', '));item(exact,'Expected post-image hashes',JSON.stringify(w.expected_post_images));item(exact,'Fixed test profile configuration hash',w.test_config_sha256);const cmd='python agent.py coding-approve --coding-root "'+w.repository+'" --workflow-id '+w.run_id;exact.append(node('p','The command only identifies the proposal. The operator CLI still requires an explicit approval decision.'));exact.append(node('pre',cmd));const b=node('button','Copy operator command','secondary');b.onclick=async()=>{try{await navigator.clipboard.writeText(cmd);b.textContent='Copied — approval is still required'}catch{b.textContent='Clipboard unavailable; select command above'}};exact.append(b);a.append(exact);c.append(a)}
if(w.candidate_status)c.append(node('p','SkillLibrary candidate: '+w.candidate_status.status+' · '+w.candidate_status.skill_id+' (unpromoted)'));if(w.recovery_journal)item(c,'Recovery journal',w.recovery_journal.status+(w.recovery_journal.journal_sha256?' · '+w.recovery_journal.journal_sha256:''));if(w.test_result){const d=node('details');d.append(node('summary','Broker test output'),node('pre',w.test_output||'Output unavailable or receipt not verified.'));c.append(d)}if(['failed','cancelled','interrupted','timed_out'].includes(w.state))c.append(node('p','Workflow did not complete successfully. '+(w.failure||''),'error'));if(['created','planning','generating','validating','reviewing'].includes(w.state)){const b=node('button','Cancel workflow','secondary');b.onclick=async()=>{try{await api('/api/workflows/'+w.run_id+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await refresh()}catch(e){$('message').textContent=e.message}};c.append(b)}return c}
function filterHistory(){const q=$('search').value.trim().toLowerCase(),s=$('state-filter').value,rows=allWorkflows.filter(w=>(!s||w.state===s)&&(!q||JSON.stringify([w.run_id,w.task,w.repository,w.role_models]).toLowerCase().includes(q)));const box=$('history-list');box.replaceChildren();for(const w of rows.slice().reverse())box.append(workflowCard(w));if(!box.childElementCount)box.append(node('p','No workflows match this search.','empty'))}
function renderWorkflows(rows){allWorkflows=rows;const box=$('workflows');box.replaceChildren();for(const w of rows.filter(x=>['created','planning','generating','validating','reviewing','awaiting_approval','approved','applying','testing'].includes(x.state)).reverse())box.append(workflowCard(w));if(!box.childElementCount)box.append(node('p','No task is running or waiting for review right now. Completed tasks are under Past tasks.','empty'));filterHistory()}
async function refresh(){try{const [w,o,s]=await Promise.all([api('/api/workflows'),api('/api/overview'),api('/api/skills')]);drawOverview(o);drawModels(o);drawSkills(s);renderWorkflows(w.workflows)}catch(e){$('message').textContent=e.message}}
async function connect(){token=$('token').value;try{fixtures=(await api('/api/fixtures')).fixtures;const o=await api('/api/overview');drawModels(o);$('preset').value='a';applyPreset();const f=$('fixture');f.replaceChildren();for(const x of fixtures){const v=node('option',x.name+' — '+x.root);v.value=x.id;f.append(v)}drawPaths();drawOverview(o);$('login').hidden=true;$('app').hidden=false;$('message').textContent='';await refresh();if(!window.lcaTimer)window.lcaTimer=setInterval(refresh,5000)}catch(e){$('message').textContent=e.message;token=''}}
$('connect').onclick=connect;$('fixture').onchange=drawPaths;$('preset').onchange=applyPreset;for(const role of ['planner','coder','reviewer'])$(role).onchange=()=>{$('preset').value='custom'};$('search').oninput=filterHistory;$('state-filter').onchange=filterHistory;$('refresh').onclick=refresh;for(const b of document.querySelectorAll('.example'))b.onclick=()=>{$('task').value=b.dataset.example;$('task').focus()};
$('submit').onclick=async()=>{const paths=[...document.querySelectorAll('#paths input:checked')].map(x=>x.value),timeout=Number($('timeout').value),attempts=Number($('attempts').value);if(!Number.isInteger(timeout)||timeout<30||timeout>600){$('submit-message').textContent='Timeout must be between 30 and 600 seconds.';return}try{const j=await api('/api/workflows',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fixture_id:$('fixture').value,task:$('task').value,paths,models:{planner:$('planner').value,coder:$('coder').value,reviewer:$('reviewer').value},limits:{timeout,attempts}})});$('submit-message').textContent='Workflow '+j.run_id+' started. Follow real stage updates below.';await refresh()}catch(e){$('submit-message').textContent=e.message}};
</script></body></html>'''
